#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/wait.h>
#include <unistd.h>

// The beacon: receive everything until the station hangs up, send it back reversed.
void serve(int fd) {
    char buf[128];
    size_t got = 0;
    ssize_t n;
    while ((n = recv(fd, buf + got, sizeof buf - got, 0)) > 0) got += n;
    for (size_t i = 0; i < got / 2; i++) {
        char tmp = buf[i];
        buf[i] = buf[got - 1 - i];
        buf[got - 1 - i] = tmp;
    }
    send(fd, buf, got, 0);
}

int main(void) {
    int fds[2];
    if (socketpair(AF_UNIX, SOCK_STREAM, 0, fds) == -1) {
        perror("socketpair");
        return 1;
    }
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 1;
    }
    if (pid == 0) {
        close(fds[0]);
        serve(fds[1]);
        close(fds[1]);
        _exit(0);
    }
    close(fds[1]);

    char msg[128];
    if (fgets(msg, sizeof msg, stdin) == NULL) msg[0] = '\0';
    msg[strcspn(msg, "\n")] = '\0';
    send(fds[0], msg, strlen(msg), 0);
    shutdown(fds[0], SHUT_WR);

    char reply[128];
    size_t got = 0;
    ssize_t n;
    while ((n = recv(fds[0], reply + got, sizeof reply - 1 - got, 0)) > 0) got += n;
    reply[got] = '\0';
    waitpid(pid, NULL, 0);
    printf("echo: %s\n", reply);
    close(fds[0]);
    return 0;
}
